package api

import (
	"net/http"

	"example.com/app/internal/service"
)

// UserHandler 处理用户查询请求（source 所在文件）
type UserHandler struct {
	Svc *service.UserService
}

// GetUser 直接把 URL 查询参数 name 透传给服务层，无任何校验
func (h *UserHandler) GetUser(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name") // SOURCE: 外部输入点1
	result, err := h.Svc.FindUserByName(r.Context(), name)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Write([]byte(result))
}

// ListUsers 第二入口：排序字段同样来自外部且未校验
func (h *UserHandler) ListUsers(w http.ResponseWriter, r *http.Request) {
	sortBy := r.URL.Query().Get("sort") // SOURCE: 外部输入点2
	rows, err := h.Svc.ListUsers(r.Context(), sortBy)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Write([]byte(rows))
}

